import PriceInput from '@/components/liquidity/dlmm/ControlPriceRange/PriceInput'
import { PriceDataType } from '@/hooks/create-pool/useCreateDLMMPool'
import useDlmmPosDetailStore from '@/store/dlmm-position/detail'
import { RangePriceType } from '@/store/dlmm/addDlmmLiquidity'
import { CetusTooltip, ErrorTips } from '@cetus/design'
import { Token } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { d, textEllipses } from '@cetus/utils'
import { Box, Center, HStack, RangeSlider, RangeSliderFilledTrack, RangeSliderThumb, RangeSliderTrack, Stack, Text, VStack } from '@chakra-ui/react'
import { useMemo, useState } from 'react'

type DlmmPositionSelectRangeProps = {
  baseToken: Token
  quoteToken: Token
  minPriceData: Omit<RangePriceType, 'tokenA' | 'tokenB'>
  maxPriceData: Omit<RangePriceType, 'tokenA' | 'tokenB'>
  handlePriceAction: (type: 'Add' | 'Sub', price: PriceDataType, isMinPrice: boolean) => void
  posMinPrice: string
  posMaxPrice: string
  handleSlider: (val: any) => void
  isDirect: boolean
}
export default function DlmmPositionSelectRange(props: DlmmPositionSelectRangeProps) {
  const { baseToken, quoteToken, minPriceData, maxPriceData, handlePriceAction, posMinPrice, posMaxPrice, handleSlider, isDirect } = props
  const { dlmmPosDetailDirect } = useDlmmPosDetailStore()
  const [isSelectRange, setIsSelectRange] = useState(false)
  const perText = useMemo(() => {
    return `${textEllipses(dlmmPosDetailDirect ? baseToken?.symbol : quoteToken?.symbol)} per ${textEllipses(dlmmPosDetailDirect ? quoteToken?.symbol : baseToken?.symbol)}`
  }, [baseToken?.symbol, quoteToken?.symbol, dlmmPosDetailDirect])

  const isShowError = useMemo(() => {
    if (!minPriceData?.price || !maxPriceData?.price) return false

    return d(minPriceData.price).gt(maxPriceData.price)
  }, [minPriceData?.price, maxPriceData?.price])

  const rangeSliderValue = useMemo(() => {
    if (minPriceData?.displayPrice && maxPriceData?.displayPrice) {
      return [minPriceData.displayPrice, maxPriceData.displayPrice]
    }
    return []
  }, [minPriceData?.displayPrice, maxPriceData?.displayPrice])
  return (
    <VStack mt="8px" w="100%">
      <VStack w="100%">
        <HStack w="100%" justifyContent="space-between">
          <Text>Select Range</Text>
          <HStack
            gap="4px"
            onClick={() => {
              setIsSelectRange(!isSelectRange)
            }}
            cursor="pointer"
            _hover={{
              p: {
                color: 'text_caption'
              },
              svg: {
                fill: 'text_caption'
              }
            }}
          >
            <CetusTooltip
              tooltip={
                <Text fontSize="12px" lineHeight="20px">
                  Customize your price range within position to optimize liquidity efficiency.
                </Text>
              }
            >
              <Center bg="primary_opacity.10" h="24px" borderRadius="12px" p="4px 6px">
                <Text fontSize="12px" color="primary">
                  Advanced
                </Text>
              </Center>
            </CetusTooltip>

            <Icon
              xlinkHref="#icon-icon_ascending_nor"
              transform={isSelectRange ? 'rotate(180deg)' : 'rotate(0deg)'}
              transition="transform 0.5s"
              fontSize="20px"
            />
          </HStack>
        </HStack>
        {isSelectRange && rangeSliderValue.length > 0 && posMinPrice && posMaxPrice && (
          <VStack w="100%" gap="8px" mt="12px">
            <RangeSlider
              min={Number(posMinPrice)}
              max={Number(posMaxPrice)}
              step={1 / 10 ** 9}
              value={rangeSliderValue as number[]}
              onChange={val => {
                handleSlider(val)
              }}
              colorScheme="teal"
            >
              <RangeSliderTrack bg="bg_secondary">
                <RangeSliderFilledTrack />
              </RangeSliderTrack>
              <RangeSliderThumb index={0} />
              <RangeSliderThumb index={1} />
            </RangeSlider>
            <HStack w="100%" justifyContent="space-between">
              <Text>{dlmmPosDetailDirect ? minPriceData?.displayPrice : minPriceData?.displayReversePrice}</Text>
              <Text>{dlmmPosDetailDirect ? maxPriceData?.displayPrice : maxPriceData?.displayReversePrice}</Text>
            </HStack>
          </VStack>
        )}
      </VStack>
      {isSelectRange && (
        <Stack mt="4px" position="relative" flexDir={{ base: 'column', lg: 'row' }} w="100%" gap={{ base: '8px', lg: '16px' }}>
          <Box opacity={1} w={{ base: '100%', lg: '50%' }}>
            <PriceInput
              title="Min Price"
              perText={perText}
              data={minPriceData!}
              direct={isDirect}
              loading={false}
              minPrice={posMinPrice}
              maxPrice={maxPriceData?.price}
              handleAddPrice={data => handlePriceAction?.('Add', data, isDirect)}
              handleSubPrice={data => handlePriceAction?.('Sub', data, isDirect)}
            />
          </Box>
          <Box opacity={1} w={{ base: '100%', lg: '50%' }}>
            <PriceInput
              title="Max Price"
              perText={perText}
              data={maxPriceData!}
              direct={isDirect}
              loading={false}
              minPrice={minPriceData?.price}
              maxPrice={posMaxPrice}
              handleAddPrice={data => handlePriceAction?.('Add', data, !isDirect)}
              handleSubPrice={data => handlePriceAction?.('Sub', data, !isDirect)}
            />
          </Box>
        </Stack>
      )}

      {isShowError && (
        <ErrorTips
          isShowIcon={false}
          tipsFontSize="12px"
          justifyContent="center"
          tips="The max price should be higher than min price."
          p="0 16px"
          h="28px"
          borderRadius="8px"
        />
      )}
    </VStack>
  )
}
