import useDlmmPosRemovePage from '@/hooks/dlmm-position/useDlmmPosRemovePage'
import useDlmmPosDetailStore from '@/store/dlmm-position/detail'
import { SelectTab, TradeInput } from '@cetus/design'
import { HTextLabelBox } from '@cetus/ui-kit'
import { isAvailableObject } from '@cetus/utils'
import { Button, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import { PositionSlider } from '../../details/RemoveBlock'
import DlmmPositionSelectRange from './DlmmPositionSelectRange'

export default function DlmmPositionRemove() {
  const {
    displayTokenA,
    displayTokenB,
    tokenBalanceA,
    tokenBalanceB,
    showDisplayTokenALock,
    showDisplayTokenBLock,
    handleAmountChange,
    tokenAmountA,
    tokenAmountB,
    dlmmPreRemoveLoading,
    isFixedDisplayTokenA,
    removeSide,
    setRemoveSide,
    isRemoveLoading,
    handleRemove,
    changeSlideFun,
    slideValue,
    minPriceData,
    maxPriceData,
    handlePriceAction,
    posMinPrice,
    posMaxPrice,
    handleSlider,
    baseToken,
    quoteToken,
    isDirect,
    getRemoveTokenBalance,
    changeSlideValue,
    btnStatusText,
    isActive,
    displayTokenALock,
    displayTokenBLock,
    setTokenAmountA,
    setTokenAmountB,
    setSlideValue,
    isReverse
  } = useDlmmPosRemovePage()

  const { showPositionSelectRange } = useDlmmPosDetailStore()

  const tabList = useMemo(
    () => [
      {
        label: 'Remove Both',
        value: 'both'
      },
      {
        label: `Only ${displayTokenA?.symbol}`,
        value: isReverse ? 'onlyB' : 'onlyA',
        afterIcon: {
          xlinkHref: '#icon-icon_tips'
        },
        tooltip: `You will remove ${displayTokenA?.symbol} from bins with prices out of the current price bin.Tokens in the current price bin will remain in the pool`
      },
      {
        label: `Only ${displayTokenB?.symbol}`,
        value: isReverse ? 'onlyA' : 'onlyB',
        afterIcon: {
          xlinkHref: '#icon-icon_tips'
        },
        tooltip: `You will remove ${displayTokenB?.symbol} from bins with prices out of the current price bin.Tokens in the current price bin will remain in the pool`
      }
    ],
    [displayTokenA, displayTokenB, isReverse]
  )

  const [isInitBalance, setIsInitBalance] = useState(true)
  useEffect(() => {
    if (isAvailableObject(minPriceData) && isAvailableObject(maxPriceData) && isInitBalance) {
      setIsInitBalance(false)
      getRemoveTokenBalance(true)
    }
  }, [minPriceData, maxPriceData, removeSide])

  return (
    <VStack w="100%" alignItems="flex-start" justifyContent="flex-start" gap="24px">
      {isActive && (
        <SelectTab
          type="outlineTab"
          isActive={(current, tab) => current === tab.value}
          wrapStyle={{
            w: '100%',
            border: 'none',
            bg: 'bg_secondary',
            h: '42px',
            justifyContent: 'flex-end',
            p: '4px'
          }}
          itemStyle={{
            w: { base: '33.33%', lg: '33.33%' },
            fontSize: '14px',
            padding: '8px',
            borderRadius: '8px',
            gap: '6px'
          }}
          tabList={tabList}
          currentTab={removeSide}
          handleChangeTab={(item: any) => {
            setRemoveSide(item?.value)
            if (item?.value !== removeSide) {
              setTokenAmountA('')
              setTokenAmountB('')
              setSlideValue('0')
            }
          }}
        />
      )}

      {showPositionSelectRange && (
        <DlmmPositionSelectRange
          minPriceData={minPriceData}
          maxPriceData={maxPriceData}
          posMinPrice={posMinPrice}
          posMaxPrice={posMaxPrice}
          handlePriceAction={handlePriceAction}
          handleSlider={handleSlider}
          baseToken={baseToken}
          quoteToken={quoteToken}
          isDirect={isDirect}
        />
      )}

      <Text>Remove Amounts</Text>
      <VStack width="100%">
        {(removeSide == 'both' || (isReverse ? removeSide == 'onlyB' : removeSide == 'onlyA')) && (
          <TradeInput
            token={displayTokenA}
            balance={tokenBalanceA}
            value={tokenAmountA}
            placeholder="0.0"
            loading={!isFixedDisplayTokenA && dlmmPreRemoveLoading}
            lock={{
              isLock: showDisplayTokenALock,
              style: {
                height: 'calc(100% + 2px)'
              }
            }}
            needRemainBalance={false}
            onChange={value => {
              handleAmountChange(value, true)
            }}
            wrapStyle={{
              h: '110px'
            }}
          />
        )}
        {(removeSide == 'both' || (isReverse ? removeSide == 'onlyA' : removeSide == 'onlyB')) && (
          <TradeInput
            token={displayTokenB}
            balance={tokenBalanceB}
            value={tokenAmountB}
            placeholder="0.0"
            loading={isFixedDisplayTokenA && dlmmPreRemoveLoading}
            lock={{
              isLock: showDisplayTokenBLock,
              style: {
                height: 'calc(100% + 2px)'
              }
            }}
            needRemainBalance={false}
            onChange={value => {
              handleAmountChange(value, false)
            }}
            wrapStyle={{
              h: '110px'
            }}
          />
        )}
      </VStack>

      <PositionSlider
        sliderBg="bg_secondary"
        percentage={slideValue}
        onChange={(value: string | number) => changeSlideValue(value)}
        textFontSize="20px"
        sliderTrackHeight="8px"
      />
      <Button
        w="100%"
        height="52px"
        fontWeight="500"
        fontSize="18px"
        isLoading={isRemoveLoading}
        onClick={handleRemove}
        isDisabled={btnStatusText.disabled}
      >
        {btnStatusText.text}
      </Button>
      <HTextLabelBox
        label="Remove Amount"
        value={`$0`}
        labelStyle={{
          fontSize: '14px'
        }}
        valueStyle={{
          fontSize: '14px'
        }}
      />
    </VStack>
  )
}
