import { Strategy } from '@/components/liquidity/dlmm/SelectStrategy'
import useDlmmPosAddPage from '@/hooks/dlmm-position/useDlmmPosAddPage'
import useDlmmPosDetailStore from '@/store/dlmm-position/detail'
import { CetusTooltip, TradeInput } from '@cetus/design'
import { HTextLabelBox, Icon } from '@cetus/ui-kit'
import { isAvailableObject } from '@cetus/utils'
import { Button, Center, HStack, Switch, Text, VStack } from '@chakra-ui/react'
import { useDebounceEffect } from 'ahooks'
import { StrategyType } from 'dd_dlmm_sdk'
import DlmmPositionSelectRange from './DlmmPositionSelectRange'

export default function DlmmPositionAdd() {
  const {
    displayTokenA,
    displayTokenB,
    tokenABalanceInfo,
    tokenBBalanceInfo,
    tokenAmountValueA,
    tokenAmountValueB,
    tokenAmountA,
    tokenAmountB,
    handleAmountChange,
    strategy,
    setStrategy,
    dlmmPreAddLoading,
    isFixedDisplayTokenA,
    totalAmount,
    btnStatusText,
    showDisplayTokenALock,
    showDisplayTokenBLock,
    displayTokenALock,
    displayTokenBLock,
    isAutoFill,
    handleAdd,
    isAddLoading,
    minPriceData,
    maxPriceData,
    posMinPrice,
    posMaxPrice,
    handlePriceAction,
    handleSlider,
    baseToken,
    quoteToken,
    dlmmPosDetailDirect,
    reCalculateResult,
    setIsAutoFill,
    setIsInitPrice,
    disabledAutoFill,
    onAutoFillChange,
    numBins
  } = useDlmmPosAddPage()

  const { showPositionSelectRange } = useDlmmPosDetailStore()

  useDebounceEffect(
    () => {
      if (isAvailableObject(minPriceData) && isAvailableObject(maxPriceData)) {
        reCalculateResult()
      }
    },
    [minPriceData, maxPriceData, displayTokenALock, displayTokenBLock, isFixedDisplayTokenA, tokenAmountA, tokenAmountB, strategy, isAutoFill],
    {
      wait: 150
    }
  )

  return (
    <VStack gap="20px" w="100%">
      <VStack w="100%" justify="space-between" mt="4px" justifyContent="flex-start" alignItems="flex-start" gap="18px">
        <Text fontSize="14px" color="primary_gray" fontWeight="500">
          Select Strategy
        </Text>
        <HStack>
          <Strategy type={StrategyType.Spot} isActive={strategy === StrategyType.Spot} onClick={() => setStrategy(StrategyType.Spot)} size="s" />
          <Strategy type={StrategyType.Curve} isActive={strategy === StrategyType.Curve} onClick={() => setStrategy(StrategyType.Curve)} size="s" />
          <Strategy
            type={StrategyType.BidAsk}
            isActive={strategy === StrategyType.BidAsk}
            onClick={() => setStrategy(StrategyType.BidAsk)}
            size="s"
          />
        </HStack>
      </VStack>
      {showPositionSelectRange && (
        <DlmmPositionSelectRange
          minPriceData={minPriceData}
          maxPriceData={maxPriceData}
          posMinPrice={posMinPrice}
          posMaxPrice={posMaxPrice}
          handlePriceAction={handlePriceAction}
          handleSlider={handleSlider}
          baseToken={baseToken}
          quoteToken={quoteToken}
          isDirect={dlmmPosDetailDirect}
        />
      )}

      <HStack w="100%" justifyContent="space-between">
        <Text>Deposit Amounts</Text>
        <HStack>
          <Text>Auto-Fill</Text>
          <Switch isDisabled={disabledAutoFill} isChecked={isAutoFill} onChange={onAutoFillChange} />
        </HStack>
      </HStack>
      <VStack w="100%">
        <TradeInput
          token={displayTokenA}
          value={tokenAmountA}
          balance={tokenABalanceInfo?.balanceFormat || ''}
          amountValue={tokenAmountValueA}
          placeholder="0.0"
          loading={!isFixedDisplayTokenA && dlmmPreAddLoading && isAutoFill}
          lock={{
            isLock: displayTokenALock || showDisplayTokenALock,
            style: {
              height: 'calc(100% + 2px)'
            }
          }}
          onChange={value => {
            handleAmountChange(value, true)
          }}
          wrapStyle={{
            height: '110px'
          }}
        />

        <TradeInput
          token={displayTokenB}
          value={tokenAmountB}
          balance={tokenBBalanceInfo?.balanceFormat || ''}
          amountValue={tokenAmountValueB}
          placeholder="0.0"
          loading={isFixedDisplayTokenA && dlmmPreAddLoading && isAutoFill}
          lock={{
            isLock: displayTokenBLock || showDisplayTokenBLock,
            style: {
              height: 'calc(100% + 2px)'
            }
          }}
          onChange={value => {
            handleAmountChange(value, false)
          }}
          wrapStyle={{
            height: '110px'
          }}
        />
      </VStack>

      <Button
        width="100%"
        height="52px"
        fontSize="18px"
        fontWeight="500"
        isDisabled={btnStatusText?.disabled}
        isLoading={isAddLoading}
        onClick={() => handleAdd()}
      >
        {btnStatusText?.text}
      </Button>
      <HTextLabelBox
        label="Deposit Amount"
        value={`$${totalAmount}`}
        labelStyle={{
          fontSize: '14px'
        }}
        valueStyle={{
          fontSize: '14px'
        }}
      />
      <HTextLabelBox
        label={
          <HStack gap="4px">
            <Text>Num Bins</Text>
            <CetusTooltip tooltip="Total price bins in this DLMM position.">
              <Center cursor="pointer">
                <Icon xlinkHref="#icon-icon_tips" svgW="20px" svgH="20px" />
              </Center>
            </CetusTooltip>
          </HStack>
        }
        value={numBins}
        labelStyle={{
          fontSize: '14px'
        }}
        valueStyle={{
          fontSize: '14px'
        }}
      />
    </VStack>
  )
}
